import threading
import time


class RateLimiter:
    def __init__(self, rate: int, per_seconds: float, clock=None):
        if rate <= 0:
            raise ValueError("rate must be positive")
        if per_seconds <= 0:
            raise ValueError("per_seconds must be positive")

        self.rate = rate
        self.per_seconds = float(per_seconds)
        self.clock = time.monotonic if clock is None else clock

        self._lock = threading.Lock()
        # key -> [tokens, last_refill_time]
        self._buckets = {}

    def _refill_locked(self, bucket, now):
        tokens, last = bucket
        if now > last:
            elapsed = now - last
            tokens = min(
                float(self.rate),
                tokens + elapsed * self.rate / self.per_seconds,
            )
            bucket[0] = tokens
            bucket[1] = now

    def allow(self, key, cost=1) -> bool:
        if not isinstance(cost, int) or isinstance(cost, bool):
            raise ValueError("cost must be an integer")
        if cost <= 0:
            raise ValueError("cost must be positive")
        if cost > self.rate:
            raise ValueError("cost must not exceed capacity")

        with self._lock:
            now = self.clock()
            bucket = self._buckets.get(key)

            if bucket is None:
                bucket = [float(self.rate), now]
                self._buckets[key] = bucket
            else:
                self._refill_locked(bucket, now)

            if bucket[0] + 1e-12 >= cost:
                bucket[0] = max(0.0, bucket[0] - cost)
                return True
            return False

    def state(self, key) -> dict:
        with self._lock:
            now = self.clock()
            bucket = self._buckets.get(key)

            if bucket is None:
                bucket = [float(self.rate), now]
                self._buckets[key] = bucket
            else:
                self._refill_locked(bucket, now)

            return {
                "tokens": round(bucket[0], 3),
                "capacity": self.rate,
            }

    def reset(self, key) -> None:
        with self._lock:
            now = self.clock()
            self._buckets[key] = [float(self.rate), now]
