        self.tokens = float(tokens)
        self.last = None


class RateLimiter:
    def __init__(self, rate: int, per_seconds: float, clock=None):
        if rate <= 0:
            raise ValueError("rate must be positive")
        if per_seconds <= 0:
            raise ValueError("per_seconds must be positive")

        self._rate = rate
        self._capacity = rate
        self._per_seconds = per_seconds
        self._clock = time.monotonic if clock is None else clock

        self._buckets = {}
        self._lock = threading.Lock()

    def _validate_cost(self, cost):
        if isinstance(cost, bool) or not isinstance(cost, int):
            raise ValueError("cost must be an integer")
        if cost <= 0 or cost > self._rate:
            raise ValueError("cost must be between 1 and rate")

    def _get_bucket(self, key):
        bucket = self._buckets.get(key)
        if bucket is None:
            bucket = _Bucket(self._capacity)
            self._buckets[key] = bucket
        return bucket

    def _refill(self, bucket, now):
        if bucket.last is None:
            bucket.last = now
            return

        elapsed = now - bucket.last
        if elapsed > 0:
            bucket.tokens = min(
                float(self._capacity),
                bucket.tokens + elapsed * self._rate / self._per_seconds,
            )
            bucket.last = now

    def allow(self, key, cost=1) -> bool:
        self._validate_cost(cost)

        with self._lock:
            now = self._clock()
            bucket = self._get_bucket(key)
            self._refill(bucket, now)

            if bucket.tokens >= cost:
                bucket.tokens -= cost
                return True
            return False

    def state(self, key) -> dict:
        with self._lock:
            now = self._clock()
            bucket = self._get_bucket(key)
            self._refill(bucket, now)

            return {
                "tokens": round(bucket.tokens, 3),
                "capacity": self._capacity,
            }

    def reset(self, key) -> None:
        with self._lock:
            bucket = self._get_bucket(key)
            bucket.tokens = float(self._capacity)
            bucket.last = None
